#include <iostream>
using namespace std;

template <typename T>
class Box {
public:
    Box(T x) : v(x) {}
    T get();
private:
    T v;
};

template <typename T>
T Box<T>::get() {
    return v;
}

int main() {
    Box<int> a({x});
    cout << a.get() << endl;
